import{_ as a,o as n,a as p,b as e}from"./app.UgfkfLuP.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器同步控制","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_sync_control/reg_sync_control"},{"text":"mem_bar","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_sync_control/mem_bar"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_sync_control/mem_bar.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_sync_control/mem_bar.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1792567581000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_sync_control/mem_bar.md"};function l(t,s,d,o,r,_){return n(),p("div",null,[...s[0]||(s[0]=[e(`<div><article class="markdown-body"><h1>mem_bar</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_sync_control.h&quot;</code>，接口命名空间为<code>asc::te::experimental</code>。</p><p><code>mem_bar</code>是Reg矢量计算函数内不同流水线之间的同步接口。接口通过模板参数指定源流水线和目的流水线：目的流水线中位于<code>mem_bar</code>之后的Unified Buffer（UB）访问，需要等待源流水线中位于<code>mem_bar</code>之前的UB访问全部完成后才能执行。</p><p>读写场景下，如果读指令和写指令使用相同的寄存器，硬件可以触发寄存器保序，指令会按照代码顺序执行，无需插入同步接口。如果使用不同的寄存器，并且需要保证两条流水线按代码顺序访问同一块UB地址空间，则需要调用本接口。写后写场景同理。</p><p>本接口仅在AIV上生效，不用于MTE流水线同步、核间同步或整核同步。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">mem_type</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">mem_type</span><span class="w"> </span><span class="n">dst</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">mem_bar</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>源流水线，类型为<code>mem_type</code>。该流水线中位于本接口之前的UB访问需要先完成，具体取值参见<a href="#mem-type-values">表2</a>。</td></tr><tr><td>dst</td><td>目的流水线，类型为<code>mem_type</code>。该流水线中位于本接口之后的UB访问等待源流水线，具体取值参见<a href="#mem-type-values">表2</a>。</td></tr></tbody></table><p><a id="mem-type-values"></a></p><p><strong>表2</strong> mem_type取值说明</p><table><thead><tr><th>mem_type取值</th><th>含义</th></tr></thead><tbody><tr><td>vec_store</td><td><code>__simd_vf__</code>函数内的矢量写UB流水线，对应寄存器到UB的数据搬出接口，例如<code>store</code>。</td></tr><tr><td>vec_load</td><td><code>__simd_vf__</code>函数内的矢量读UB流水线，对应UB到寄存器的数据搬入接口，例如<code>load</code>。</td></tr><tr><td>scalar_store</td><td><code>__simd_vf__</code>函数内的标量写UB流水线。</td></tr><tr><td>scalar_load</td><td><code>__simd_vf__</code>函数内的标量读UB流水线。</td></tr><tr><td>vec_all</td><td><code>__simd_vf__</code>函数内所有矢量读写UB流水线。</td></tr><tr><td>scalar_all</td><td><code>__simd_vf__</code>函数内所有标量读写UB流水线。</td></tr></tbody></table><p><a id="mem-bar-supported-combinations"></a></p><p><strong>表3</strong> <code>src</code>和<code>dst</code>组合取值说明</p><table><thead><tr><th>src</th><th>dst</th></tr></thead><tbody><tr><td><code>mem_type::vec_store</code></td><td><code>mem_type::vec_load</code></td></tr><tr><td><code>mem_type::vec_load</code></td><td><code>mem_type::vec_store</code></td></tr><tr><td><code>mem_type::vec_store</code></td><td><code>mem_type::vec_store</code></td></tr><tr><td><code>mem_type::vec_store</code></td><td><code>mem_type::scalar_load</code></td></tr><tr><td><code>mem_type::vec_store</code></td><td><code>mem_type::scalar_store</code></td></tr><tr><td><code>mem_type::vec_load</code></td><td><code>mem_type::scalar_store</code></td></tr><tr><td><code>mem_type::scalar_store</code></td><td><code>mem_type::vec_load</code></td></tr><tr><td><code>mem_type::scalar_store</code></td><td><code>mem_type::vec_store</code></td></tr><tr><td><code>mem_type::scalar_load</code></td><td><code>mem_type::vec_store</code></td></tr><tr><td><code>mem_type::vec_all</code></td><td><code>mem_type::vec_all</code></td></tr><tr><td><code>mem_type::vec_all</code></td><td><code>mem_type::scalar_all</code></td></tr><tr><td><code>mem_type::scalar_all</code></td><td><code>mem_type::vec_all</code></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>仅支持<a href="#mem-bar-supported-combinations">表3</a>列出的模板参数组合，其他组合会产生编译期错误。</li><li>读写依赖场景下，如果读指令和写指令使用相同的寄存器，会触发寄存器保序，无需额外调用本接口。</li><li>仅在不同流水线访问的UB地址存在依赖时使用本接口，冗余同步会降低性能。</li><li>本接口应在<code>__simd_vf__</code>函数或<code>__simd_callee__</code>函数中调用。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中，<code>data</code>既是搬入数据的源Tensor，也是搬出数据的目的Tensor。后一次循环中的矢量读UB操作与前一次循环中的矢量写UB操作访问同一块UB地址空间，因此，每次读取前需要调用<code>mem_bar</code>，使矢量读流水线等待矢量写流水线完成。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Process</span><span class="p">(</span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">data</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">T</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">::</span><span class="n">data_type</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">mem_bar</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">mem_type</span><span class="o">::</span><span class="n">vec_store</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">mem_type</span><span class="o">::</span><span class="n">vec_load</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">data</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">        </span><span class="n">value</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// 使用value完成寄存器计算。</span>
<span class="w">        </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store</span><span class="p">(</span><span class="n">data</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">value</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const h=a(c,[["render",l]]);export{m as __pageData,h as default};
